    // "invalid binary enable" implies checking if enable is a valid trigger. 
    // Typically 0 is disabled, non-zero is enabled. 
    // If enabled, check limits/count.
    int config_ok = 1;
    if (ag_input.enable != 0) {
        if (!isfinite(ag_config.angle_limit_rad) || ag_config.angle_limit_rad > ADCS_PI ||
            !isfinite(ag_config.rate_limit_rad_s) ||
            ag_config.required < 1U || ag_config.required > 20U) {
            config_ok = 0;
        }
    }

    if (!config_ok) {
        ag_state.mode = AG_FAULT;
        goto set_fault_output;
    }

