    adcs_quat_t q_curr_n, q_tgt_n;
    if (adcs_quat_normalize(ag_input.current_q_bi, &q_curr_n) != ADCS_OK ||
        adcs_quat_normalize(ag_input.target_q_bi, &q_tgt_n) != ADCS_OK) {
        ag_state.mode = AG_FAULT;
        goto set_fault_output;
    }

    // Step 4: Compute Angle
    double dot_val = adcs_quat_abs_dot(&q_curr_n, &q_tgt_n);
    if (dot_val > 1.0) dot_val = 1.0;
    double angle_rad = 2.0 * acos(dot_val);

