    double rate_norm = adcs_vec3_norm(ag_input.rate_rad_s);
    double rate_energy = adcs_vec3_dot(ag_input.rate_rad_s, ag_input.rate_rad_s);

    // Step 6: Mode Decision
    ag_mode_t next_mode = ag_state.mode;
    unint32 next_good = ag_state.good;

    if (ag_input.enable == 0) {
        // Disabled case
        next_mode = AG_SLEW;
        next_good = 0;
    } else {
        // Enabled case
        if (angle_rad <= ag_config.angle_limit_rad && rate_norm <= ag_config.rate_limit_rad_s) {
            next_good++;
            if (next_good >= ag_config.required) {
                next_mode = AG_SETTLED;
            } else {
                next_mode = ag_state.mode; // Preserve current mode
            }
        } else {
            // Limit exceeded
            next_mode = AG_SLEW;
            next_good = 0;
        }
    }

    // Update State
    ag_state.mode = next_mode;
    ag_state.good = next_good;

    // Set Normal Output
    ag_output.mode = next_mode;
    ag_output.good = next_good;
    ag_output.angle_rad = angle_rad;
    ag_output.rate_norm_rad_s = rate_norm;
    ag_output.rate_energy = rate_energy;
    return;

