adcs_quat_t q_curr_norm, q_target_norm;
adcs_quat_t q_rel;
double angle_rad;
double rate_norm;
double rate_energy;
int valid_inputs = 1;

/* 1. 输入校验：NULL, degenerate/nonfinite telemetry, invalid binary enable, negative limits or count outside 1..20 */
if (ag_input.current_q_bi == NULL || ag_input.target_q_bi == NULL || ag_input.rate_rad_s == NULL) {
    valid_inputs = 0;
} else if (!adcs_is_finite_vec3(ag_input.rate_rad_s)) {
    valid_inputs = 0;
} else if (adcs_quat_normalize(ag_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
    valid_inputs = 0;
} else if (adcs_quat_normalize(ag_input.target_q_bi, &q_target_norm) != ADCS_OK) {
    valid_inputs = 0;
} else if (!isfinite(ag_config.angle_limit_rad) || ag_config.angle_limit_rad < 0.0 || ag_config.angle_limit_rad > ADCS_PI) {
    valid_inputs = 0;
} else if (!isfinite(ag_config.rate_limit_rad_s) || ag_config.rate_limit_rad_s < 0.0) {
    valid_inputs = 0;
} else if (ag_config.required < 1U || ag_config.required > 20U) {
    valid_inputs = 0;
}

/* 任何违规选择 SLEW 并清除证据；禁用重置 (Latched FAULT) */
if (!valid_inputs) {
    ag_state.mode = AG_FAULT;
    ag_state.good = 0;
    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

/* 2. Normalize current and target quaternions, form the relative rotation */
/* q_rel represents rotation from current to target in body frame */
adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
q_rel = adcs_quat_multiply(&q_curr_conj, &q_target_norm);

/* 3. Compute shortest angle plus body-rate norm */
/* Shortest angle is 2 * acos(|w|) for unit quaternion */
double abs_w = fabs(q_rel.w);
if (abs_w > 1.0) abs_w = 1.0;
angle_rad = 2.0 * acos(abs_w);

rate_norm = adcs_vec3_norm(ag_input.rate_rad_s);
rate_energy = adcs_vec3_dot(ag_input.rate_rad_s, ag_input.rate_rad_s);

/* 4. Settling decision table logic */
if (!ag_input.enable) {
    /* disabled -> SLEW, clear to zero */
    ag_state.mode = AG_SLEW;
    ag_state.good = 0;
} else {
    /* enabled check */
    if ((angle_rad <= ag_config.angle_limit_rad) && (rate_norm <= ag_config.rate_limit_rad_s)) {
        /* angle <= limit AND rate <= limit */
        if (ag_state.mode != AG_SETTLED) {
            ag_state.mode = AG_SETTLED;
        }
        /* increment good-sample evidence */
        if (ag_state.good < ag_config.required) {
            ag_state.good++;
        }
    } else {
        /* either limit exceeded -> SLEW, clear to zero */
        ag_state.mode = AG_SLEW;
        ag_state.good = 0;
    }
}

/* 5. Publish outputs */
ag_output.mode = ag_state.mode;
ag_output.good = ag_state.good;
ag_output.angle_rad = angle_rad;
ag_output.rate_norm_rad_s = rate_norm;
ag_output.rate_energy = rate_energy;

